                        int page_size, int slot_bytes, int token_stride,
                        unsigned long long dst_offset, cudaStream_t stream) {
  if (num_pages == 0) return;
  const bool aligned = (slot_bytes % 16 == 0) && (dst_offset % 16 == 0);
