  for (std::size_t p = 0; p < num_pages; ++p) {
    auto* dst = static_cast<std::uint8_t*>(const_cast<void*>(peer_dst_ptrs[p])) +
                dst_page_offsets[p];
    std::memcpy(dst, scratch.data() + p * scratch_per_page, scratch_per_page);
  }
}

